// Package osroot provides traversal-resistant file I/O helpers built on os.Root
// (Go 1.24+). These helpers ensure that file operations cannot escape a scoped
// directory, preventing symlink attacks and TOCTOU races at the kernel level.
//
// These wrappers predate Go 1.25, which added native ReadFile/WriteFile/MkdirAll
// (etc.) on *os.Root; they remain as the codebase's stable, consistent helper
// surface and delegate to the native methods where those now exist.
//
// Errors from these functions are returned unwrapped so that callers can use
// os.IsNotExist() and errors.Is() directly without losing the original sentinel.
package osroot

import (
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"slices"
	"strings"
	"sync"
)

// ReadFile reads the named file relative to root using os.Root for
// traversal-resistant access. The kernel enforces that the read cannot
// escape the root directory, preventing symlink and TOCTOU attacks.
func ReadFile(root *os.Root, name string) ([]byte, error) {
	f, err := root.Open(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error for os.IsNotExist checks
	}
	defer f.Close()

	data, err := io.ReadAll(f)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error
	}
	return data, nil
}

// WriteFile writes data to the named file relative to root using os.Root
// for traversal-resistant access. Creates the file if it doesn't exist,
// truncates it if it does. The kernel enforces that the write cannot escape
// the root directory.
func WriteFile(root *os.Root, name string, data []byte, perm os.FileMode) (retErr error) {
	f, err := root.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, perm)
	if err != nil {
		return err //nolint:wrapcheck // preserve original error for os.IsNotExist checks
	}
	defer func() {
		if closeErr := f.Close(); closeErr != nil && retErr == nil {
			retErr = closeErr
		}
	}()

	if _, err := f.Write(data); err != nil {
		return err //nolint:wrapcheck // preserve original error
	}
	return nil
}

// MkdirAll creates the directory named by name, along with any necessary
// parents, relative to root. The kernel enforces containment: a name that
// escapes root (absolute, or climbing above it via "..") is rejected. Already-
// existing directories are tolerated, like os.MkdirAll. This thin wrapper keeps
// the package's os.Root helper surface (alongside ReadFile/WriteFile/Remove)
// consistent at call sites.
func MkdirAll(root *os.Root, name string, perm os.FileMode) error {
	return root.MkdirAll(name, perm) //nolint:wrapcheck // preserve original error for errors.Is/os.IsNotExist
}

// Remove removes the named file relative to root using os.Root for
// traversal-resistant access. Returns nil if the file doesn't exist.
func Remove(root *os.Root, name string) error {
	err := root.Remove(name)
	if err != nil && !os.IsNotExist(err) {
		return err //nolint:wrapcheck // preserve original error
	}
	return nil
}

// ReadDir reads the named directory relative to root, returning its entries
// sorted by filename, like os.ReadDir. os.Root has no ReadDir method of its
// own, so this is the sanctioned way to list a directory without falling back
// to an unconfined os.ReadDir on a joined path.
func ReadDir(root *os.Root, name string) ([]os.DirEntry, error) {
	f, err := root.Open(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error for os.IsNotExist checks
	}
	defer f.Close()

	entries, err := f.ReadDir(-1)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error
	}
	slices.SortFunc(entries, func(a, b os.DirEntry) int {
		return strings.Compare(a.Name(), b.Name())
	})
	return entries, nil
}

// ErrSymlinkedPath reports a symlink found where a real directory was required.
// Callers match it with errors.Is.
var ErrSymlinkedPath = errors.New("path component is a symlink")

// MkdirAllNoSymlink is MkdirAll with one added refusal: if any component of
// name already exists as a symlink, it returns an error wrapping
// ErrSymlinkedPath instead of creating anything.
//
// os.Root alone is not enough here. It refuses to follow a symlink that escapes
// the root, but a symlink pointing elsewhere *inside* the root is followed
// silently, and an escaping one fails later with whatever errno the first open
// happens to hit — which surfaces to the user as an unexplained I/O failure far
// from the cause. Checking at the point the directory is established turns both
// into one named error while the caller still has the context to report it.
//
// This is a check against a symlink that is already there — planted by hand, or
// arriving with a checkout — not a defence against one appearing between the
// check and the Mkdir. That race is not worth closing: os.Root still bounds the
// result to inside the root either way, so the worst case is the silent-follow
// behaviour that existed before this function.
func MkdirAllNoSymlink(root *os.Root, name string, perm os.FileMode) error {
	for _, prefix := range dirPrefixes(name) {
		info, err := root.Lstat(prefix)
		if err != nil {
			if os.IsNotExist(err) {
				continue // MkdirAll below creates it as a real directory
			}
			return err //nolint:wrapcheck // preserve the original for errors.Is/os.IsNotExist
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("%s: %w", prefix, ErrSymlinkedPath)
		}
	}
	return root.MkdirAll(name, perm) //nolint:wrapcheck // preserve original error for errors.Is/os.IsNotExist
}

// SymlinkPaths walks dir within root and returns the names of every symlink it
// finds, in the root's coordinates. It never follows one, so a symlinked
// directory is reported and not descended into.
//
// A missing dir yields no names and no error: nothing there is nothing wrong.
func SymlinkPaths(root *os.Root, dir string) ([]string, error) {
	var found []string
	err := fs.WalkDir(root.FS(), dir, func(name string, d fs.DirEntry, err error) error {
		if err != nil {
			if name == dir && os.IsNotExist(err) {
				return nil
			}
			return err
		}
		if d.Type()&fs.ModeSymlink != 0 {
			found = append(found, name)
		}
		return nil
	})
	if err != nil {
		return nil, err //nolint:wrapcheck // caller names the directory it asked about
	}
	return found, nil
}

// dirPrefixes returns each ancestor of name in order, including name itself,
// and nothing for "." or "". Names are slash-separated, as os.Root requires.
func dirPrefixes(name string) []string {
	cleaned := path.Clean(name)
	if cleaned == "." || cleaned == "" || cleaned == "/" {
		return nil
	}
	parts := strings.Split(strings.TrimPrefix(cleaned, "/"), "/")
	prefixes := make([]string, 0, len(parts))
	for i := range parts {
		prefixes = append(prefixes, strings.Join(parts[:i+1], "/"))
	}
	return prefixes
}

// sharedRoots is the process-wide registry behind Shared. Entire anchors roots
// at three directories — .entire, the git common dir, and the worktree root —
// and each had its own memoized map before this existed. One registry means one
// place that decides a directory is opened at most once, and one Reset.
var (
	sharedMu    sync.Mutex
	sharedRoots = map[string]*os.Root{}
)

// Shared returns a process-wide *os.Root for dir, opening it at most once. The
// returned root is owned by the registry and shared with every other caller: do
// not close it.
//
// dir must be absolute. A relative key would name different directories as the
// process moved, which is the whole failure mode these roots exist to remove.
//
// A missing directory is returned unwrapped so callers can classify it with
// os.IsNotExist as well as errors.Is.
func Shared(dir string) (*os.Root, error) {
	if !filepath.IsAbs(dir) {
		return nil, fmt.Errorf("osroot: %q is not absolute", dir)
	}
	cleaned := filepath.Clean(dir)

	sharedMu.Lock()
	defer sharedMu.Unlock()

	if root, ok := sharedRoots[cleaned]; ok {
		return root, nil
	}
	root, err := os.OpenRoot(cleaned)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, err //nolint:wrapcheck // see doc comment
		}
		return nil, fmt.Errorf("open %s: %w", cleaned, err)
	}
	sharedRoots[cleaned] = root
	return root, nil
}

// Forget closes and drops the cached root for one directory, leaving the rest of
// the registry alone.
//
// Call it immediately before deleting or replacing a single rooted directory.
// ResetShared is the wrong tool there: it clears every anchor, and a caller
// rebuilding one cache directory has no business invalidating the handles other
// packages hold on .entire or .git. The plugin index cache is the case this
// exists for — its directory is removed and recreated by `git clone` while the
// process runs, so a root cached across that would be a handle to an unlinked
// inode.
//
// A directory that was never opened is not an error: forgetting is idempotent.
func Forget(dir string) {
	if !filepath.IsAbs(dir) {
		return
	}
	cleaned := filepath.Clean(dir)

	sharedMu.Lock()
	defer sharedMu.Unlock()
	if root, ok := sharedRoots[cleaned]; ok {
		_ = root.Close()
		delete(sharedRoots, cleaned)
	}
}

// ResetShared closes and forgets every root Shared handed out. Call it after
// deleting or replacing a directory a root was held on: a root that outlives its
// directory is a handle to an unlinked inode, so writes through it succeed and
// land nowhere.
func ResetShared() {
	sharedMu.Lock()
	defer sharedMu.Unlock()
	for key, root := range sharedRoots {
		_ = root.Close()
		delete(sharedRoots, key)
	}
}

// Package entiredir owns access to the repository's .entire directory.
//
// Every non-test read and write under .entire goes through the single *os.Root
// this package hands out, rather than through an absolute path assembled by the
// caller. Two properties follow from that, and neither survives if a call site
// reverts to os.ReadFile/os.WriteFile on a joined path:
//
//   - Containment. .entire holds paths named from agent-supplied session IDs,
//     tool-use IDs, and tree paths. A root confines every open to the directory
//     at the kernel level, so a crafted name cannot escape it, and a symlink
//     swapped in between resolution and open (TOCTOU) surfaces as an error
//     rather than a redirected write.
//   - One directory handle per worktree. The root is opened once and memoized,
//     so the hot hook paths stop paying an OpenRoot per state file, and every
//     consumer observes the same directory even if .entire is renamed or
//     replaced underneath a long-running process.
//
// Creation is deliberately lazy and split across two entry points. Open creates
// .entire because its callers are about to write; OpenForRead never creates,
// because a command that only looks must leave an untouched repo untouched.
// That distinction is load-bearing for logging in particular: the log file is
// created by the first line actually written, so a command that logs nothing
// (completion, version, help) must not leave an .entire behind.
//
// Reset exists for the paths that delete the directory (entire disable,
// entire clean) and for tests. A cached root that outlives its directory is a
// handle to an unlinked inode: writes through it succeed and land nowhere.
package entiredir

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// dirPerm is the mode .entire is created with. It matches the mode the
// directory already had when each consumer created its own subdirectory.
const dirPerm = 0o750

// Open returns the shared *os.Root for the current worktree's .entire
// directory, creating the directory if it does not exist. Use it from write
// paths; read-only callers want OpenForRead.
//
// The returned root is owned by this package and shared with every other
// caller. Do not close it.
func Open(ctx context.Context) (*os.Root, error) {
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return nil, err
	}
	return OpenAt(worktreeRoot)
}

// OpenForRead is Open without creating .entire. A missing directory is
// reported as fs.ErrNotExist, which callers classify with errors.Is.
func OpenForRead(ctx context.Context) (*os.Root, error) {
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return nil, err
	}
	return OpenAtForRead(worktreeRoot)
}

// OpenAt is Open for an explicit worktree root, for the callers that already
// resolved one (or that act on a worktree other than the current directory).
func OpenAt(worktreeRoot string) (*os.Root, error) {
	return open(worktreeRoot, true)
}

// OpenAtForRead is OpenForRead for an explicit worktree root.
func OpenAtForRead(worktreeRoot string) (*os.Root, error) {
	return open(worktreeRoot, false)
}

// Opener returns a thunk that calls Open when invoked, for consumers that are
// handed their storage up front but must not touch the disk until they first
// write (see logging.Config.Root).
func Opener(ctx context.Context) func() (*os.Root, error) {
	return func() (*os.Root, error) { return Open(ctx) }
}

// OpenerAt returns a thunk that calls OpenAt when invoked.
func OpenerAt(worktreeRoot string) func() (*os.Root, error) {
	return func() (*os.Root, error) { return OpenAt(worktreeRoot) }
}

// Path returns the absolute path of the current worktree's .entire directory.
// It is for messages and for the few consumers that must hand a path to an
// external process; it is not an invitation to do I/O on the result.
func Path(ctx context.Context) (string, error) {
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return "", err
	}
	return filepath.Join(worktreeRoot, paths.EntireDir), nil
}

// Reset closes and forgets every cached root. Call it after deleting .entire:
// a root cached across the deletion refers to an unlinked directory, so writes
// through it succeed and land nowhere.
//
// The registry is shared with the other anchors, so this clears them too. That
// is the behaviour teardown wants — a repo whose .entire just went away is not a
// repo whose .git root is worth keeping — and tests get one reset to call.
func Reset() {
	osroot.ResetShared()
}

// Name converts a repo-relative path under .entire (for example
// paths.EntireTmpDir) to a name relative to the .entire root. The repo-relative
// constants stay as they are because git paths, settings display, and gitignore
// entries all need them; this is the one-line bridge to root-relative I/O.
//
// A path outside .entire is an error rather than a silent passthrough: the
// alternative is a name that resolves inside .entire but means something else.
func Name(repoRelPath string) (string, error) {
	cleaned := filepath.ToSlash(filepath.Clean(filepath.FromSlash(repoRelPath)))
	if cleaned == paths.EntireDir {
		return ".", nil
	}
	rest, ok := strings.CutPrefix(cleaned, paths.EntireDir+"/")
	if !ok || rest == "" {
		return "", fmt.Errorf("%q is not under %s", repoRelPath, paths.EntireDir)
	}
	return rest, nil
}

// MustName is Name for package-level constants that are known to be under
// .entire. It panics on a path that is not, which can only be a programming
// error in a literal.
func MustName(repoRelPath string) string {
	name, err := Name(repoRelPath)
	if err != nil {
		panic(err)
	}
	return name
}

// anchor resolves the directory .entire sits in: the git worktree root, falling
// back to the current directory only when there is provably no repository.
//
// The fallback is narrow and it is load-bearing — `entire enable` runs in a
// directory that is not a repository yet — but the reason it is *safe* is that
// paths.WorktreeRoot no longer depends on `git` being runnable. It answers from
// the subprocess when it can and from a walk up for a .git entry when it cannot,
// so an error from it means "no .git anywhere above here", not "git did not
// run". Inside a repository the fallback is therefore unreachable, which is what
// makes it different from the paths.AbsPath fallback it replaces: that one fired
// on any resolve failure, including `git` off $PATH inside a real repo, and then
// silently gave an agent working in a subdirectory its own .entire beside itself.
//
// Callers that name a worktree themselves use OpenAt and never reach this.
func anchor(ctx context.Context) (string, error) {
	if worktreeRoot, err := paths.WorktreeRoot(ctx); err == nil {
		return worktreeRoot, nil
	}
	cwd, err := os.Getwd() //nolint:forbidigo // no repository above us; see the doc comment
	if err != nil {
		return "", fmt.Errorf("resolve %s location: %w", paths.EntireDir, err)
	}
	return cwd, nil
}

// PathTo returns the absolute path of repoRelPath, which must name something
// under .entire. It exists for the consumers that carry an absolute path in
// their own API — settings resolves one per layer and hands it back to callers
// that print it — so those resolve through this package's anchor rather than
// paths.AbsPath, whose relative fallback is the thing anchor exists to avoid.
func PathTo(ctx context.Context, repoRelPath string) (string, error) {
	if _, err := Name(repoRelPath); err != nil {
		return "", err
	}
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return "", err
	}
	return filepath.Join(worktreeRoot, filepath.FromSlash(repoRelPath)), nil
}

func open(worktreeRoot string, create bool) (*os.Root, error) {
	if worktreeRoot == "" {
		return nil, errors.New("entiredir: worktree root is required")
	}
	abs, err := filepath.Abs(worktreeRoot)
	if err != nil {
		return nil, fmt.Errorf("resolve %s: %w", worktreeRoot, err)
	}
	return openDir(filepath.Join(abs, paths.EntireDir), create)
}

// openDir is the one place a *os.Root over a .entire directory is created. Every
// entry point funnels here so the create/no-create split stays in a single
// branch; osroot.Shared owns the open-at-most-once part.
func openDir(dir string, create bool) (*os.Root, error) {
	if create {
		if err := os.MkdirAll(dir, dirPerm); err != nil {
			return nil, fmt.Errorf("create %s: %w", dir, err)
		}
	}
	return osroot.Shared(dir) //nolint:wrapcheck // Shared names the directory, and returns a missing one unwrapped for errors.Is
}

// OpenPath returns the shared root for the .entire directory containing p,
// together with p's name within it, creating the directory if needed.
// OpenPathForRead is the same without creation.
//
// These exist for the consumers that already carry an absolute path — settings
// resolves one per layer, and hands it back to callers that print it — so those
// APIs keep their shape while the open itself still goes through the one root.
// A path not under a .entire directory yields ok=false from Split and an error
// here; callers that legitimately handle both (settings also reads clone
// preferences out of .git) branch on that rather than guessing.
func OpenPath(p string) (root *os.Root, name string, err error) {
	return openPath(p, true)
}

// OpenPathForRead is OpenPath without creating .entire.
func OpenPathForRead(p string) (root *os.Root, name string, err error) {
	return openPath(p, false)
}

// Split splits a path that lies under a .entire directory into that directory
// and the name of the path within it. It is lexical: the path is cleaned and the
// innermost ".entire" component wins, which is the directory that actually
// contains the file if a repo is ever checked out inside another repo's .entire.
//
// A relative path is accepted, because paths.AbsPath still falls back to one
// when it cannot resolve a worktree root and callers hand that value straight
// through. The walk is component-by-component with filepath rather than a split
// on separators so a Windows volume name survives being rejoined.
func Split(p string) (entireDir, name string, ok bool) {
	cleaned := filepath.Clean(p)
	rest := cleaned
	for {
		dir, base := filepath.Split(rest)
		if base == "" {
			return "", "", false
		}
		if base == paths.EntireDir {
			rel, relErr := filepath.Rel(rest, cleaned)
			// rel == "." means the caller named the directory itself, which is
			// not a file within it.
			if relErr != nil || rel == "." || paths.IsRelativeTraversal(rel) {
				return "", "", false
			}
			return rest, filepath.ToSlash(rel), true
		}
		if dir == "" {
			return "", "", false // reached the start of a relative path
		}
		parent := filepath.Clean(dir)
		if parent == rest {
			return "", "", false // reached the filesystem root
		}
		rest = parent
	}
}

func openPath(p string, create bool) (*os.Root, string, error) {
	dir, name, ok := Split(p)
	if !ok {
		return nil, "", fmt.Errorf("%q is not under a %s directory", p, paths.EntireDir)
	}
	// A relative path is rejected rather than resolved against the current
	// directory: that is the cwd anchor anchor() refuses, reached by another
	// route. Callers resolve their path from the worktree root before getting
	// here.
	if !filepath.IsAbs(dir) {
		return nil, "", fmt.Errorf("%q is not absolute; resolve it against the worktree root first", p)
	}
	root, err := openDir(dir, create)
	if err != nil {
		return nil, "", err
	}
	return root, name, nil
}
=====GITDIR=====
// Package gitdir owns access to the git common directory — .git in an ordinary
// checkout, and the main repository's .git when running from a linked worktree.
//
// Entire keeps a lot of state there, deliberately: session state, advisory
// locks, the checkpoint push queue, the redaction prefix cache, investigation
// runs, review manifests, and the captured checkpoint-sync election all live in
// the common dir rather than under .entire, because they are per-clone and must
// not be committed or walked into a checkpoint tree. That makes this directory
// the same kind of trust surface .entire is, and it gets the same treatment: one
// *os.Root per common dir, opened once and shared, with every read and write
// resolved as a name inside it.
//
// Two properties come from that, and neither survives a call site reverting to
// os.ReadFile on a joined path:
//
//   - Containment. Names here are built from agent-supplied session IDs and
//     investigation run IDs. Several call sites carry hand-written comments
//     explaining that an unvalidated ID would be a path-traversal sink feeding
//     os.RemoveAll. A root makes that structural instead of a precondition each
//     caller has to keep honouring.
//   - One directory handle per clone. The resolver shells out to git; before
//     this package, strategy.GetGitCommonDir did so on *every* call with no
//     cache at all, on hook paths.
//
// Unlike .entire there is no create/no-create split: the common dir is the
// repository, so it always exists by the time anything here is called. What
// needs creating are Entire's own subdirectories inside it, via
// osroot.MkdirAllNoSymlink.
package gitdir

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

var (
	// resolveMu guards the resolved-path cache, which is keyed by the working
	// directory the answer was derived in (see CommonDir).
	resolveMu     sync.RWMutex
	cachedDir     string
	cachedFromCwd string
)

// CommonDir returns the absolute path of the git common directory, caching the
// result per working directory.
//
// Absolute is the load-bearing word. `git rev-parse --git-common-dir` answers
// relative to the process's directory — from a subdirectory it returns
// "../../../.git" — and the two implementations this replaced passed that
// straight through, so every path built on it was only valid while the process
// stayed put. Resolving it once here means a stored lock path or queue path
// still names the same file later, and it is what lets Open hold a handle
// rather than re-resolving a string.
func CommonDir(ctx context.Context) (string, error) {
	cwd, err := os.Getwd() //nolint:forbidigo // cache key, and the base the git answer is relative to
	if err != nil {
		cwd = ""
	}

	resolveMu.RLock()
	if cachedDir != "" && cachedFromCwd == cwd {
		cached := cachedDir
		resolveMu.RUnlock()
		return cached, nil
	}
	resolveMu.RUnlock()

	// The environment is deliberately inherited rather than scrubbed with
	// gitrepo.EnvWithoutRepoOverrides. The rule that exists for cmd.Dir/-C
	// subprocesses is about not silently operating on the hook's repo when the
	// caller meant a different one; here the hook's repo IS the target, so a
	// GIT_DIR git exported to us is the right answer, not contamination.
	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
	cmd.Dir = "."
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("failed to get git common dir: %w", err)
	}

	dir, err := filepath.Abs(strings.TrimSpace(string(output)))
	if err != nil {
		return "", fmt.Errorf("resolve git common dir: %w", err)
	}

	resolveMu.Lock()
	cachedDir = dir
	cachedFromCwd = cwd
	resolveMu.Unlock()

	return dir, nil
}

// ClearCache forgets the resolved path. Tests that change directory call it;
// production does not need to, because the cache is keyed by cwd.
func ClearCache() {
	resolveMu.Lock()
	cachedDir = ""
	cachedFromCwd = ""
	resolveMu.Unlock()
}

// Open returns the shared *os.Root over the git common directory. The returned
// root is owned by this package and shared with every other caller; do not
// close it.
func Open(ctx context.Context) (*os.Root, error) {
	dir, err := CommonDir(ctx)
	if err != nil {
		return nil, err
	}
	return OpenAt(dir)
}

// OpenAt is Open for an explicit git directory — the common dir for callers that
// already resolved one or that act on another clone, and the per-worktree git
// dir for the few things that genuinely live there rather than in the common dir
// (the rebase/cherry-pick sequence markers).
func OpenAt(commonDir string) (*os.Root, error) {
	if commonDir == "" {
		return nil, errors.New("gitdir: common dir is required")
	}
