	if home, err := os.UserHomeDir(); err == nil {
		allowed = appendResolved(allowed, home)
	}
	if tmpDir := os.TempDir(); tmpDir != "" {
		allowed = appendResolved(allowed, tmpDir)
	}

	return allowed
