		return LocalManifest{}, false, fmt.Errorf("read manifest %s: %w", latest, err)
	}
	var m LocalManifest
	if err := json.Unmarshal(b, &m); err != nil {
		return LocalManifest{}, false, fmt.Errorf("decode manifest %s: %w", latest, err)
	}
	return m, true, nil
}

