		return nil, fmt.Errorf("invalid run ID: %w", err)
	}

	root, err := s.root()
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil //nolint:nilnil // no store => no such run
		}
		return nil, fmt.Errorf("open investigation store: %w", err)
	}
