def return_type(sig):
    t = sig.rstrip()
    assert t.endswith("{")
    t = t[:-1].rstrip()
    if not t.endswith(")"):
        return t.rsplit(")", 1)[1].strip()  # single unparenthesised result
    depth = 0
    for i in range(len(t) - 1, -1, -1):
        if t[i] == ")":
            depth += 1
        elif t[i] == "(":
            depth -= 1
            if depth == 0:
                return t[i:]
    raise SystemExit("unbalanced: " + sig)

